import { type MuscleGroupId, type MuscleId } from "@fa/shared";
import { muscleGroupLabel } from "@/lib/catalogLabels";
import { cn } from "@/lib/utils";

// Anatomical icon with the target muscle highlighted. Each icon is one scene
// (front torso, back, legs, forearm…) from public/muscle-icons, generated by
// muscle-groups-icons/trace.py. It's drawn through <use> so the layers pick up
// the --muscle-* theme variables (styles.css): the body follows light/dark and
// the highlight takes the brand primary.

// Muscles without an icon of their own borrow the closest neighbour's.
const MUSCLE_ICON: Record<MuscleId, string> = {
  anterior_deltoid: "shoulders_anterior_deltoid",
  lateral_deltoid: "shoulders_anterior_deltoid",
  posterior_deltoid: "shoulders_posterior_deltoid",
  pectoralis_major_clavicular: "chest_pectoralis_major",
  pectoralis_major_sternal: "chest_pectoralis_major",
  biceps_brachii: "arms_and_forearms_biceps",
  brachialis: "arms_and_forearms_brachialis",
  brachioradialis: "arms_and_forearms_brachialis",
  forearm_flexors: "arms_and_forearms_forearm_extensors",
  forearm_extensors: "arms_and_forearms_forearm_extensors",
  triceps_brachii: "arms_and_forearms_triceps",
  rectus_abdominis: "core_rectus_abdominis",
  external_obliques: "core_external_obliques",
  internal_obliques: "core_obliques",
  trapezius: "back_trapezius",
  // The "rhomboids" source image highlights the lats/upper-back block.
  latissimus_dorsi: "back_rhomboids",
  infraspinatus: "back_rhomboids",
  teres_major: "back_rhomboids",
  rhomboids: "back_rhomboids",
  // back_erector_spinae.png has no highlight; the lower-back one fits.
  erector_spinae: "back_latissimus_dorsi_lower",
  gluteus_maximus: "hips_and_glutes_gluteus_maximus",
  gluteus_medius: "hips_and_glutes_gluteus_maximus",
  rectus_femoris: "legs_anterior_quadriceps",
  tensor_fasciae_latae: "legs_anterior_quadriceps",
  vastus_lateralis: "legs_anterior_vastus",
  vastus_medialis: "legs_anterior_vastus",
  sartorius: "core_hip_flexors",
  gracilis: "core_hip_flexors",
  biceps_femoris: "legs_posterior_hamstrings",
  semitendinosus: "legs_posterior_hamstrings",
  semimembranosus: "legs_posterior_hamstrings",
  gastrocnemius: "legs_posterior_gastrocnemius",
  tibialis_anterior: "legs_posterior_gastrocnemius",
  soleus: "legs_posterior_soleus",
};

// For callers that only know groups (machines).
const GROUP_ICON: Record<MuscleGroupId, string> = {
  shoulders: "shoulders_anterior_deltoid",
  chest: "chest_pectoralis_major",
  arms_and_forearms: "arms_and_forearms_biceps",
  core: "core_rectus_abdominis",
  back: "back_rhomboids",
  hips_and_glutes: "hips_and_glutes_gluteus_maximus",
  legs_anterior: "legs_anterior_quadriceps",
  legs_posterior: "legs_posterior_hamstrings",
};

export const muscleGroupNames = (groups: readonly MuscleGroupId[]) =>
  groups.map(muscleGroupLabel).join(", ");

export function MuscleMap({
  groups,
  muscles = [],
  className,
  title,
}: {
  groups: readonly MuscleGroupId[];
  /** Specific muscles, most important first; the first one picks the icon.
   *  Falls back to the first group when none has an icon. */
  muscles?: readonly MuscleId[];
  className?: string;
  /** Tooltip / accessible label. Defaults to the highlighted group names. */
  title?: string;
}) {
  const icon =
    muscles.map((m) => MUSCLE_ICON[m]).find(Boolean) ??
    groups.map((g) => GROUP_ICON[g]).find(Boolean);
  if (!icon) return null;
  const label = title ?? muscleGroupNames(groups);

  return (
    <svg
      viewBox="0 0 1 1"
      role="img"
      aria-label={label}
      className={cn("aspect-square shrink-0", className)}
    >
      <title>{label}</title>
      <use href={`/muscle-icons/${icon}.svg#m`} width="1" height="1" />
    </svg>
  );
}
